"""Ch 12, second set of explanation items (25), adapted from WS1, WS2 (G2/G3) and the mastery tests.
L3-L5 items carry keypoints so they can be answered in the student's own words."""
from .. import figs, sketches as S
from .base import register_explain
from .ch12 import WEBS, _fig, _pop_curve

KP = lambda label, *phr: {"label": label, "any": list(phr)}

